import CollapsibleCard from '../CollapsibleCard'
import { CollapsibleTableStyle } from './index.style'
import PropTypes from 'prop-types'
import { DisplayFlexCCC, Row } from '../../commonStyle/index.style'
import CustomText from '../CustomText'
import { AgentColorPallette } from '../../configs/colorPallete'
import SingleImgContainer from '../SingleImgContainer'
import { PHOTO } from '../../images'
import ZoomImg from '../zoomImg'

function CollapsibleTable (props) {
  const getNoImgContainer = (widthClass) => {
    return (
      <DisplayFlexCCC className={`no-img ${widthClass}`}>
        <img alt='dashboard-img' src={PHOTO} className='uploaded-image' />
      </DisplayFlexCCC>
    )
  }

  const getValueContainer = (item = {}) => {
    if (item.type === 'img') {
      return item.value ? (
        <ZoomImg
          src={item.value}
          imgContainer={
            <SingleImgContainer
              minWidth='50px'
              imgUrl={item.value}
              imgClassName='single-img-margin'
              showVerified
            />
          }
        />
      ) : getNoImgContainer('single-img-margin')
    }
    const text = item.value
    return (
      <CustomText
        size='13px'
        textAlign={item.newline ? 'left' : 'right'}
        className='item-value'
        color={item.color || AgentColorPallette.regular}
        weight={800}
      >
        {text || '-'}
      </CustomText>
    )
  }

  return (
    <CollapsibleTableStyle>
      <CollapsibleCard
        titleClassName='card-title'
        className='collapse-card'
        title={props.title}
        isOpen
      >
        {
          props.items.map((item, index) => {
            const showSeprator = index !== props.items.length - 1
            return (
              <div key={index}>
                <Row className='item-padding' align='stretch' flexDirection={item.newline ? 'column' : 'row'} justify='space-between'>
                  <CustomText size='13px' color={AgentColorPallette.fontDarkerGrey}>
                    {item.head}
                  </CustomText>
                  <div className={item.newline ? '' : 'value-container'}> {getValueContainer(item)} </div>
                </Row>
                {showSeprator && <hr className='separator' />}
              </div>
            )
          })
        }
      </CollapsibleCard>
    </CollapsibleTableStyle>
  )
}

CollapsibleTable.propTypes = {
  title: PropTypes.string,
  items: PropTypes.arrayOf(PropTypes.shape({
    head: PropTypes.string,
    value: PropTypes.string,
    newline: PropTypes.bool,
    type: PropTypes.string
  }))
}

export default CollapsibleTable
