
import isObject from 'lodash/isObject'
import { useCallback } from 'react'
import { Row } from '../../commonStyle/index.style'
import { AgentColorPallette } from '../../configs/colorPallete'
import BranchCard from '../../containers/Private/Policy/components/BranchCard'
import { LANG_STRINGS } from '../../lang'
import CustomText from '../CustomText'
import { QuickViewPackageCardStyle } from './index.style'

function QuickViewPackageCard (props) {
  const { periodText = LANG_STRINGS.marineCargoPeriod, className, branch } = props

  const renderKeyVal = useCallback((title, value) => {
    return (
      <div>
        <CustomText
          size='10px'
          color={AgentColorPallette.fontDarkerGrey}
          weight={700}
        >
          {title}
        </CustomText>
        <CustomText
          size='13px'
          color={AgentColorPallette.regular}
          weight={600}
        >
          {value}
        </CustomText>
      </div>
    )
  }, [])

  return (
    <QuickViewPackageCardStyle className={className}>
      <div className='logo-container'>
        <div className='package-img-box'>
          {
            props.packageLogo && <img className='package-img' src={props.packageLogo} alt='package-logo' />
          }
        </div>
        {
          props.providerName &&
            <CustomText
              color={AgentColorPallette.regular}
              size='10px'
              weight={600}
              top='10px'
              textAlign='center'
            >
              {props.providerName}
            </CustomText>
        }
        <CustomText
          color={AgentColorPallette.regular}
          weight='800'
          size='15px'
          textAlign='center'
        >
          {props.packageName}
        </CustomText>
      </div>
      {
        branch && isObject(branch) &&
          <BranchCard branch={branch} />
      }
      <hr className='separator' />
      <Row justify='space-between' className='amount-section'>
        <div>
          <CustomText
            size='15px'
            color={AgentColorPallette.black}
            weight={700}
          >
            {props.amount}
          </CustomText>
          <CustomText
            size='10px'
            color={AgentColorPallette.fontDarkerGrey}
            weight={700}
          >
            {periodText}
          </CustomText>
        </div>
        {
          !!props.points && (
            <div>
              <CustomText
                size='10px'
                color={AgentColorPallette.fontDarkerGrey}
                weight={700}
              >
                {LANG_STRINGS.pointsSmall}
              </CustomText>
              <CustomText
                size='13px'
                color={AgentColorPallette.regular}
                weight={600}
              >
                {props.points}
              </CustomText>
            </div>
          )
        }
        {
          !!props.commission && (
            <div>
              <CustomText
                size='10px'
                color={AgentColorPallette.fontDarkerGrey}
                weight={700}
                textAlign='right'
              >
                {LANG_STRINGS.commission}
              </CustomText>
              <CustomText
                size='13px'
                color={AgentColorPallette.regular}
                weight={600}
              >
                {props.commission}
              </CustomText>
            </div>
          )
        }
      </Row>
      {
        props.annualBenefit && props.roomFee &&
          <Row justify='space-between' className='amount-section pt-0'>
            {renderKeyVal(LANG_STRINGS.annualBenifits, props.annualBenefit)}
            {renderKeyVal(LANG_STRINGS.roomFee, props.roomFee)}
          </Row>
      }
    </QuickViewPackageCardStyle>
  )
}

export default QuickViewPackageCard
