import { ConfigUrl } from '../../../../configs/url'
import { MARINE_CARGO } from '../../../../constants/pkgCode'

export const MARINE_CARGO_ACTIONS = {
  GET_REGION_CODES_REQUEST: 'GET_REGION_CODES_REQUEST',
  GET_REGION_CODES: 'GET_REGION_CODES',

  GET_SHIP_MATERIAL_REQUEST: 'GET_SHIP_MATERIAL_REQUEST',
  GET_SHIP_MATERIAL: 'GET_SHIP_MATERIAL',

  GET_APPLICATION_DETAIL_REQUEST: 'GET_APPLICATION_DETAIL_REQUEST',
  GET_APPLICATION_DETAIL: 'GET_APPLICATION_DETAIL',

  CREATE_APPLICATION_REQUEST: 'CREATE_APPLICATION_REQUEST',
  CREATE_APPLICATION: 'CREATE_APPLICATION',

  UPDATE_APPLICATION_REQUEST: 'UPDATE_APPLICATION_REQUEST',
  UPDATE_APPLICATION: 'UPDATE_APPLICATION',

  UPDATE_CUSTOMER_APPLICATION_REQUEST: 'UPDATE_CUSTOMER_APPLICATION_REQUEST',
  UPDATE_CUSTOMER_APPLICATION: 'UPDATE_CUSTOMER_APPLICATION',

  SUBMIT_APPLICATION_REQUEST: 'SUBMIT_APPLICATION_REQUEST',
  SUBMIT_APPLICATION: 'SUBMIT_APPLICATION',

  CHANGE_DISCOUNT_REQUEST: 'CHANGE_DISCOUNT_REQUEST',
  CHANGE_DISCOUNT: 'CHANGE_DISCOUNT',

  GET_PACKAGES_REQUEST: 'GET_PACKAGES_REQUEST',
  GET_PACKAGES: 'GET_PACKAGES',

  GET_PACKAGE_DETAIL_REQUEST: 'GET_PACKAGE_DETAIL_REQUEST',
  GET_PACKAGE_DETAIL: 'GET_PACKAGE_DETAIL',

  GET_CUSTOMER_APPLICATION_DETAIL_REQUEST: 'GET_CUSTOMER_APPLICATION_DETAIL_REQUEST',
  GET_CUSTOMER_APPLICATION_DETAIL: 'GET_CUSTOMER_APPLICATION_DETAIL',

  GET_COUNTRY_LIST_REQUEST: 'GET_COUNTRY_LIST_REQUEST',
  GET_COUNTRY_LIST: 'GET_COUNTRY_LIST'
}

export const getRegionCodes = (payload) => ({
  type: MARINE_CARGO_ACTIONS.GET_REGION_CODES_REQUEST,
  payload: {
    ...payload,
    method: 'get',
    url: ConfigUrl.getRegionCode
  }
})

export const getPackagesList = (payload) => ({
  type: MARINE_CARGO_ACTIONS.GET_PACKAGES_REQUEST,
  payload: {
    ...payload,
    method: 'post',
    url: ConfigUrl.getPackages(MARINE_CARGO)
  }
})

