import { resetError, updateLoader, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import get from 'lodash/get'
import { useCallback, useEffect, useMemo, useState } from 'react'
import { withRouter } from 'react-router'
import { DisplayCircleIcon, DisplayFlexRCC } from '../../../../../../commonStyle/index.style'
import { Container, CustomText } from '../../../../../../components'
import ButtonWithIcon from '../../../../../../components/ButtonWithIcon'
import CollapsibleTable from '../../../../../../components/CollapsibleTable'
import CustomCheckbox from '../../../../../../components/CustomCheckbox'
import InsuranceInfoCard from '../../../../../../components/InsuranceInfoCard'
import QuickViewPackageCard from '../../../../../../components/QuickViewPackageCard'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import StepsHeader from '../../../../../../components/StepsHeader'
import TransactionCard from '../../../../../../components/TransactionCard'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { formatMoney, getParamsFromUri } from '../../../../../../helpers/utility'
import { INFO, SEND_GOLD_ICON } from '../../../../../../images'
import { LANG_STRINGS } from '../../../../../../lang'
import TermsNConditionModal from '../../../../Application/components/TermsNConditionModal'

import { getAttachmentDetailCard, getDeliveryDetailCard, getItemDetailCard, getPolicyDetailCard, getCustomerDetailCard, getHardcopyDetailCard } from '../../../constants'
import { useChangeDiscount, useGetApplicationDetail, useSubmitApplication } from '../../../state/hooks/useMarineCargo'
import { ApplicationPreviewStyle } from './index.style'

function ApplicationPreviewContainer (props) {
  const policyId = getParamsFromUri.call({ props }, 'policyId')
  const [{ GET_APPLICATION_DETAIL_LOADER, CHANGE_DISCOUNT_LOADER, SUBMIT_APPLICATION_LOADER }, dispatchLoader] = useLoaderContextValue()
  const [{ getApplicationDetailData = {} }, getApplicationDetailRequest] = useGetApplicationDetail()
  const [, submitApplicationRequest] = useSubmitApplication()
  const [, changeDiscountRequest] = useChangeDiscount()
  const [isTermsChecked, setIsTermsChecked] = useState(false)
  const [showTermsModal, setShowTermsModal] = useState(false)
  const [
    {
      GET_APPLICATION_DETAIL_ERROR, getApplicationDetailStatus,
      CHANGE_DISCOUNT_ERROR, changeDiscountStatus,
      SUBMIT_APPLICATION_ERROR, submitApplicationStatus
    },
    dispatchError
  ] = useErrorContextValue()

  useEffect(() => {
    if (GET_APPLICATION_DETAIL_LOADER === undefined) {
      getApplicationDetailRequest({
        policyId: policyId
      })
    }
  }, [getApplicationDetailRequest,
    GET_APPLICATION_DETAIL_LOADER, policyId
  ])

  useEffect(() => {
    return () => {
      dispatchLoader(updateLoader({
        GET_APPLICATION_DETAIL_LOADER: undefined,
        CHANGE_DISCOUNT_LOADER: undefined,
        SUBMIT_APPLICATION_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  useEffect(() => {
    if (GET_APPLICATION_DETAIL_ERROR && getApplicationDetailStatus) {
      ShowSnackbar.error({
        visible: true,
        text: getApplicationDetailStatus
      })
      dispatchError(resetError({
        getApplicationDetailStatus: ''
      }))
    }
    if (CHANGE_DISCOUNT_ERROR && changeDiscountStatus) {
      ShowSnackbar.error({
        visible: true,
        text: changeDiscountStatus
      })
      dispatchError(resetError({
        changeDiscountStatus: ''
      }))
    }
    if (SUBMIT_APPLICATION_ERROR && submitApplicationStatus) {
      ShowSnackbar.error({
        visible: true,
        text: submitApplicationStatus
      })
      dispatchError(resetError({
        submitApplicationStatus: ''
      }))
    }
    if (submitApplicationStatus === 'success') {
      props.history.push(`/payment/marine-cargo-protection/${policyId}`)
      dispatchError(resetError({
        submitApplicationStatus: ''
      }))
    }
    if (changeDiscountStatus === 'success') {
      getApplicationDetailRequest({
        policyId: policyId
      })
      dispatchError(resetError({
        changeDiscountStatus: ''
      }))
    }
  }, [GET_APPLICATION_DETAIL_ERROR, getApplicationDetailStatus,
    CHANGE_DISCOUNT_ERROR, changeDiscountStatus,
    dispatchError, getApplicationDetailRequest, policyId,
    submitApplicationStatus, SUBMIT_APPLICATION_ERROR,
    props.history
  ])

  const handleEditDiscount = useCallback((newDiscount) => {
    changeDiscountRequest({
      body: {
        discount: newDiscount,
        user_id: ''
      },
      policyId: policyId
    })
  }, [policyId, changeDiscountRequest])

  const handleSubmit = useCallback(() => {
    submitApplicationRequest({
      policyId: policyId
    })
  }, [policyId, submitApplicationRequest])

  const handleSaveOffer = useCallback(() => {
    ShowSnackbar.success({
      visible: true,
      text: LANG_STRINGS.offerSaved
    })
    setTimeout(() => {
      props.history.push(`/transactions/${policyId}/details`)
    }, 2000)
  }, [props.history, policyId])

  const showShipClass = useMemo(() => {
    return get(getApplicationDetailData, 'policy_detail.ship_class', '') !== 'non-class'
  }, [getApplicationDetailData])

  const handleTermsCheckBox = useCallback((useCase) => {
    setIsTermsChecked(useCase)
    setShowTermsModal(false)
  }, [])

  return (
    <Container
      title='Kargo'
      hideBottomTabs
      displayBackButton
      backBtnId='kargoStepBack_1'
      loader={CHANGE_DISCOUNT_LOADER || GET_APPLICATION_DETAIL_LOADER || SUBMIT_APPLICATION_LOADER}
      showSideMenuIcon
      sideMenuItems={[{ head: LANG_STRINGS.saveOffer, handleClick: handleSaveOffer }]}
    >
      <ApplicationPreviewStyle>
        <StepsHeader leftText='Kargo' current='4' totalSteps='4' />
        <CustomText
          color={AgentColorPallette.regular}
          weight={600}
          className='icon-text'
          top='15px'
          bottom='15px'
          padLeft='1rem'
          padRight='1rem'
          size='13px'
        >
          <DisplayCircleIcon width='18px' height='18px' bgColor={AgentColorPallette.black}>
            <img src={INFO} alt='INFO' className='info-img' />
          </DisplayCircleIcon>&nbsp;&nbsp;
          <span>
            {LANG_STRINGS.makeSureAllEnteredInfoIsCorrect}.
          </span>
        </CustomText>
        <hr className='separator' />
        <div className='content'>
          <QuickViewPackageCard
            packageLogo={get(getApplicationDetailData, 'policy_detail.provider.logo_url', '')}
            providerName={showShipClass && get(getApplicationDetailData, 'policy_detail.provider.name', '')}
            packageName={get(getApplicationDetailData, 'policy_detail.package.name', '')}
            amount={formatMoney(get(getApplicationDetailData, 'policy_detail.premium_breakup.base_premium.premium', 0), 0)}
            period={get(getApplicationDetailData, 'policy_detail.applicable_period', 0)}
            points={get(getApplicationDetailData, 'policy_detail.points', 0)}
            branch={getApplicationDetailData?.policy_detail?.provider_branch}
          />
          <InsuranceInfoCard
            isShowDisclaimer
            tnc={get(getApplicationDetailData, 'policy_detail.tnc.data', [])}
            benefit={get(getApplicationDetailData, 'policy_detail.benefit.data[0].description', '')}
            claims={get(getApplicationDetailData, 'policy_detail.claims.[0].description', '')}
          />
          <TransactionCard
            commission={get(getApplicationDetailData, 'product.commission')}
            maxDiscount={get(getApplicationDetailData, 'policy_detail.max_discount')}
            subTotal={get(getApplicationDetailData, 'policy_detail.sub_total')}
            discountPercent={get(getApplicationDetailData, 'policy_detail.discount_percentage')}
            basicPremium={get(getApplicationDetailData, 'policy_detail.basic_premium')}
            totalTax={0}
            stampDuty={get(getApplicationDetailData, 'policy_detail.stamp_duty')}
            adminFee={get(getApplicationDetailData, 'admin_fee')}
            serviceFee={get(getApplicationDetailData, 'service_charge')}
            discount={get(getApplicationDetailData, 'policy_detail.discount')}
            totalBill={get(getApplicationDetailData, 'subtotal_bill', 0) + get(getApplicationDetailData, 'discount', 0)}
            handleEditDiscount={handleEditDiscount}
          />
          <hr className='separator' />
          <CustomText
            color={AgentColorPallette.black}
            size='15px'
            weight={800}
            bottom='15px'
            top='10px'
          >
            {LANG_STRINGS.dataChecking}
          </CustomText>
          <CollapsibleTable
            title={LANG_STRINGS.policyDetails}
            items={getPolicyDetailCard(getApplicationDetailData)}
          />
          <hr className='separator' />
          <CustomText
            color={AgentColorPallette.black}
            size='15px'
            weight={800}
            bottom='15px'
            top='10px'
          >
            {LANG_STRINGS.insuredObject}
          </CustomText>
          <CollapsibleTable
            title={LANG_STRINGS.itemDetails}
            items={getItemDetailCard(getApplicationDetailData)}
          />
          <CollapsibleTable
            title={LANG_STRINGS.delivery}
            items={getDeliveryDetailCard(getApplicationDetailData)}
          />
          <CollapsibleTable
            title={LANG_STRINGS.attachment}
            items={getAttachmentDetailCard(getApplicationDetailData)}
          />
          <CollapsibleTable
            title={LANG_STRINGS.policyHolderData}
            items={getCustomerDetailCard(getApplicationDetailData)}
          />
          <CollapsibleTable
            title={LANG_STRINGS.printPolicy}
            items={getHardcopyDetailCard(getApplicationDetailData)}
          />
          <DisplayFlexRCC onClick={() => setShowTermsModal(!showTermsModal)}>
            <CustomCheckbox
              isChecked={isTermsChecked}
              onChange={() => {}}
            />
            <CustomText
              color={AgentColorPallette.black}
              weight={700}
              dangerouslySetInnerHTML={{
                __html: LANG_STRINGS.agreeWithTermsConditionsCargo
              }}
            />
          </DisplayFlexRCC>
        </div>
        <div className='bottom-action-container'>
          <DisplayFlexRCC className='bottom-continue-btn'>
            <ButtonWithIcon
              disabled={!isTermsChecked}
              id='cargoStepSubmit_4'
              className='start-btn'
              text={LANG_STRINGS.makePayment}
              icon={SEND_GOLD_ICON}
              iconRight
              onClick={handleSubmit}
            />
          </DisplayFlexRCC>
        </div>
        {
          showTermsModal && (
            <TermsNConditionModal
              isOpen={showTermsModal}
              tncData={getApplicationDetailData.product.tnc.data}
              onAccept={() => handleTermsCheckBox(true)}
              onReject={() => handleTermsCheckBox(false)}
            />
          )
        }
        <ShowSnackbar hideOkay />
      </ApplicationPreviewStyle>
    </Container>
  )
}

export default withRouter(ApplicationPreviewContainer)
